B.au2=new A.iT("Allah","\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647","Belief in Allah, His Oneness, His names, and His attributes, without likening Him to creation.")
B.au7=new A.iT("The angels","\u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629","Belief in the angels, created from light. They do not disobey Allah.")
B.au4=new A.iT("The books","\u0627\u0644\u0643\u062a\u0628","Belief in the books Allah revealed, including the Torah, the Gospel, the Psalms, and the Quran, which is the final Book.")
B.au0=new A.iT("The messengers","\u0627\u0644\u0631\u0633\u0644","Belief in the messengers, from Adam to Muhammad \ufdfa, the seal of the prophets.")
B.atZ=new A.iT("The Last Day","\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631","Belief in the resurrection, the reckoning, Paradise, and Hellfire.")
B.au5=new A.iT("The decree","\u0627\u0644\u0642\u062f\u0631","Belief that everything, the good of it and the bad of it, is by the decree of Allah.")
B.a34=A.a(s([B.au2,B.au7,B.au4,B.au0,B.atZ,B.au5]),t.ud)
B.atR=new A.QQ("Six Pillars of Iman","\u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646",B.a34,null)
B.au6=new A.iT("Shahadah","\u0627\u0644\u0634\u0647\u0627\u062f\u0629","Testifying that none has the right to be worshipped except Allah, and that Muhammad is the Messenger of Allah.")
B.au8=new A.iT("Salah","\u0627\u0644\u0635\u0644\u0627\u0629","The five daily prayers: Fajr, Dhuhr, Asr, Maghrib, and Isha.")
B.au3=new A.iT("Zakat","\u0627\u0644\u0632\u0643\u0627\u0629","The obligatory charity on wealth that reaches the nisab, after a lunar year. On cash it is 2.5%.")
B.au1=new A.iT("Sawm","\u0627\u0644\u0635\u0648\u0645","Fasting the month of Ramadan, from the start of Fajr until Maghrib.")
B.au_=new A.iT("Hajj","\u0627\u0644\u062d\u062c","The pilgrimage to Makkah once in a lifetime, for whoever is able to make the journey.")
B.a4v=A.a(s([B.au6,B.au8,B.au3,B.au1,B.au_]),t.ud)
B.atS=new A.QQ("Five Pillars of Islam","\u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645",B.a4v,null)
B.atT=new A.QR(null)
B.fq=new A.vw(0,"pressed")
